mapper.select:
SELECT a.id AS id, xkzbh as license_number, b.name as institutionName, c.itemname as licenseDeviceName, d.itemname as ladderConfigModel, e.fullname as region, fzrq as "originalIssueDate", fzrq_f as copyIssueDate, a.sbzt as deviceStatus, a.status_zb AS originalEntryStatus, a.status_fb AS copyEntryStatus FROM history_license a LEFT JOIN history_dept b ON a.pzdwmc = b.duns LEFT JOIN history_dict c ON a.xksbmc = c.dictid AND a.xksbmc IS NOT NULL LEFT JOIN history_dict d ON a.jtpzjx = d.dictid AND a.jtpzjx IS NOT NULL left join history_area e on a.sbpzdzCode = e.id
and c.itemname = #{req.licenseDevice}
and d.itemname = #{req.ladderConfig}
and ( (xkzbh like concat('%', #{req.keyword}, '%')) or (b.name like concat('%', #{req.keyword}, '%')) )
and e.fullname like concat('%', #{req.area}, '%')
GROUP BY a.id
